
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_hlta_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_hlta", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.463774350821802e+00, -2.452157563274515e+00, -2.435524146131708e+00, -2.411795635607047e+00, -2.378166196166993e+00, -2.331030100136802e+00, -2.266111269438091e+00, -2.178849026332317e+00, -2.064131927375026e+00, -1.907971294539216e+00, -1.623670395642354e+00, -1.011917307625686e+00, -5.418559833384291e-01, -4.450560823571358e-01, -4.042948422910109e-01, -3.471909081943302e-01, -2.819131737371540e-01, -2.155667147036676e-01, -1.527318608085084e-01, -9.627847107870241e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


